const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const secret = String($env.N8N_WEBHOOK_SECRET || '').trim();
const incoming = String(headers['x-mdoctor-webhook-secret'] || headers['X-MDoctor-Webhook-Secret'] || body.webhook_secret || '').trim();
if (secret && incoming !== secret) throw new Error('Invalid webhook secret');

const flowEnv = String($env.FLOW_ENV || 'staging').toLowerCase();
if (flowEnv !== 'staging') throw new Error('FLOW_ENV must be staging');

const backendUrl = String($env.BACKEND_URL_STAGING || 'https://mdoctor-backend-staging-staging.up.railway.app').replace(/\/$/, '');
if (backendUrl.includes('web-production')) throw new Error('Backend staging must not be production web');

const atendimentoId = String(body.atendimento_id || body.atendimentoId || '').trim();
const phone = String(body.phone || body.from || body.telefone || body.whatsapp || '').replace(/\D/g, '');
if (!phone && !atendimentoId) throw new Error('phone or atendimento_id required');

const correlationId = headers['x-correlation-id'] || headers['X-Correlation-Id'] || body.correlation_id || `pay-${Date.now()}`;
const idempotencyKey = String(headers['idempotency-key'] || headers['Idempotency-Key'] || body.idempotency_key || `payment-${phone || atendimentoId}-${Date.now()}`);

const payload = {
  from: phone ? `+${phone.startsWith('55') ? phone : `55${phone}`}` : undefined,
  telefone: phone,
  atendimento_id: atendimentoId || undefined,
  payment_status: 'paid',
  pagamento_status: 'CONFIRMADO',
  payment_confirmed: true,
  pagamento: true,
  source: 'n8n-stripe-payment-staging',
  protocol: 'staging-payment-v1',
  correlation_id: correlationId
};

return [{
  json: {
    backendUrl,
    correlationId,
    idempotencyKey,
    payload,
    headers: {
      'Content-Type': 'application/json',
      'X-MDoctor-Webhook-Secret': secret,
      'X-Correlation-Id': correlationId,
      'Idempotency-Key': idempotencyKey,
      'X-N8N-Workflow': 'stripe-payment-staging'
    }
  }
}];
